"""Human-readable register catalog for the Thermia Calibra POC."""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class RegisterDefinition:
    """One Thermia Genesis register used by this proof-of-concept."""

    key: str
    name: str
    space: str
    address: int
    data_type: str
    scale: float
    unit: str | None = None
    nan: int | None = None


